content.content:
1790	  // ─── Mentions ─────────────────────────────────────────────────────
1791	
1792	  /**
1793	   * List mentions for a given user.
1794	   *
1795	   * Returns mentions sorted by `createdAt` descending (newest first).
1796	   *
1797	   * @param userName - The user name whose mentions to list
1798	   * @param options - Optional flags
1799	   * @param options.includeReads - Include read mentions alongside unread
1800	   * @returns Array of mention results, or a AgentrackError
1801	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
1802	   * @throws {AgentrackError} USER_NOT_FOUND if the user is not registered
1803	   */
1804	  async mentionsList(
1805	    userName: string,
1806	    options?: { includeReads?: boolean },
1807	  ): Promise<MentionsListResult> {
1808	    const trackerDir = resolveTrackerDir(this.cwd);
1809	    if (!trackerDir) {
1810	      throw new AgentrackError(
1811	        ErrorCodes.NOT_INITIALIZED.result,
1812	        "No .agentrack/ directory found. Run `agt init` first.",
1813	        ErrorCodes.NOT_INITIALIZED.exitCode,
1814	      );
1815	    }
1816	
1817	    const lowerName = userName.toLowerCase();
1818	
1819	    // Validate user is registered
1820	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
1821	    if (!users.users.find((u) => u.name === lowerName)) {
1822	      return new AgentrackError(
1823	        ErrorCodes.USER_NOT_FOUND.result,
1824	        `User "${lowerName}" not found.`,
1825	        ErrorCodes.USER_NOT_FOUND.exitCode,
1826	      );
1827	    }
1828	
1829	    const mentions = readMentionsFile(trackerDir);
1830	    const entries = mentions[lowerName] ?? [];
1831	
1832	    // Filter by read status unless includeReads is set
1833	    const filtered = options?.includeReads
1834	      ? entries
1835	      : entries.filter((e) => !e.isRead);
1836	
1837	    return filtered
1838	      .map((entry) => ({
1839	        id: entry.id,
1840	        mentionedBy: entry.mentionedBy,
1841	        issueId: entry.issueId,
1842	        commentId: entry.commentId,
1843	        createdAt: entry.createdAt,
1844	        isRead: entry.isRead,
1845	      }))
1846	      .sort((a, b) => (a.createdAt > b.createdAt ? -1 : a.createdAt < b.createdAt ? 1 : 0));
1847	  }
1848	
1849	  /**
1850	   * View a single mention with full context.
1851	   *
1852	   * Resolves the mention to the actual comment content and issue title.
1853	   *
1854	   * @param mentionId - The mention ID to look up
1855	   * @returns The mention with comment and issue context, or a AgentrackError
1856	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
1857	   * @throws {AgentrackError} MENTION_NOT_FOUND if the mention ID doesn't exist
1858	   * @throws {AgentrackError} COMMENT_NOT_FOUND if the source comment was deleted
1859	   */
1860	  async mentionsView(mentionId: string): Promise<MentionsViewResult> {
1861	    const trackerDir = resolveTrackerDir(this.cwd);
1862	    if (!trackerDir) {
1863	      throw new AgentrackError(
1864	        ErrorCodes.NOT_INITIALIZED.result,
1865	        "No .agentrack/ directory found. Run `agt init` first.",
1866	        ErrorCodes.NOT_INITIALIZED.exitCode,
1867	      );
1868	    }
1869	
1870	    const found = findMentionById(trackerDir, mentionId);
1871	    if (!found) {
1872	      return new AgentrackError(
1873	        ErrorCodes.MENTION_NOT_FOUND.result,
1874	        `Mention \`${mentionId}\` not found.`,
1875	        ErrorCodes.MENTION_NOT_FOUND.exitCode,
1876	      );
1877	    }
1878	
1879	    const { entry } = found;
1880	
1881	    // Resolve issue title
1882	    const index = await readIndex(trackerDir);
1883	    const issueEntry = findEntry(index, entry.issueId);
1884	
1885	    // Resolve comment content by replaying events
1886	    if (!issueEntry) {
1887	      return new AgentrackError(
1888	        ErrorCodes.NOT_FOUND.result,
1889	        `Issue \`${entry.issueId}\` not found.`,
1890	        ErrorCodes.NOT_FOUND.exitCode,
1891	      );
1892	    }
1893	
1894	    const issueFilePath = join(trackerDir, issueEntry.path);
1895	    if (!existsSync(issueFilePath)) {
1896	      return new AgentrackError(
1897	        ErrorCodes.ISSUE_MISSING.result,
1898	        `Issue file for \`${entry.issueId}\` is missing.`,
1899	        ErrorCodes.ISSUE_MISSING.exitCode,
1900	      );
1901	    }
1902	
1903	    const events = await replayEvents(issueFilePath);
1904	    const comments = computeComments(events);
1905	    const comment = comments.find((c) => c.id === entry.commentId);
1906	
1907	    if (!comment) {
1908	      return new AgentrackError(
1909	        ErrorCodes.COMMENT_NOT_FOUND.result,
1910	        `Comment \`${entry.commentId}\` not found (may have been deleted).`,
1911	        ErrorCodes.COMMENT_NOT_FOUND.exitCode,
1912	      );
1913	    }
1914	
1915	    return {
1916	      mention: entry,
1917	      comment: {
1918	        id: comment.id,
1919	        author: comment.author,
1920	        content: comment.content,
1921	        timestamp: comment.timestamp,
1922	        ...(comment.editedAt ? { editedAt: comment.editedAt } : {}),
1923	      },
1924	      issue: {
1925	        id: entry.issueId,
1926	        title: issueEntry.title,
1927	      },
1928	    };
1929	  }
1930	
1931	  /**
1932	   * Mark a mention as read.
1933	   *
1934	   * Auth constraint: only the mentionedUser can mark a mention as read.
1935	   *
1936	   * @param mentionId - The mention ID to mark as read
1937	   * @returns `{ result: "OK" }` on success, or a AgentrackError
1938	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
1939	   * @throws {AgentrackError} MENTION_NOT_FOUND if the mention ID doesn't exist
1940	   * @throws {AgentrackError} MENTION_ACCESS_DENIED if the authenticated user is not the mentioned user
1941	   * @throws {AgentrackError} TOKEN_REQUIRED if no token provided in auth-required mode
1942	   */
1943	  async mentionsRead(mentionId: string): Promise<MentionsReadResult> {
1944	    const trackerDir = resolveTrackerDir(this.cwd);
1945	    if (!trackerDir) {
1946	      throw new AgentrackError(
1947	        ErrorCodes.NOT_INITIALIZED.result,
1948	        "No .agentrack/ directory found. Run `agt init` first.",
1949	        ErrorCodes.NOT_INITIALIZED.exitCode,
1950	      );
1951	    }
1952	
1953	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
1954	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
1955	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
1956	    if (authResult instanceof AgentrackError) return authResult;
1957	    const callerName = authResult.author;
1958	
1959	    const found = findMentionById(trackerDir, mentionId);
1960	    if (!found) {
1961	      return new AgentrackError(
1962	        ErrorCodes.MENTION_NOT_FOUND.result,
1963	        `Mention \`${mentionId}\` not found.`,
1964	        ErrorCodes.MENTION_NOT_FOUND.exitCode,
1965	      );
1966	    }
1967	
1968	    if (found.entry.mentionedUser !== callerName) {
1969	      return new AgentrackError(
1970	        ErrorCodes.MENTION_ACCESS_DENIED.result,
1971	        `Only the mentioned user (${found.entry.mentionedUser}) can mark this mention as read.`,
1972	        ErrorCodes.MENTION_ACCESS_DENIED.exitCode,
1973	      );
1974	    }
1975	
1976	    // Update the mention
1977	    const mentions = readMentionsFile(trackerDir);
1978	    const userEntries = mentions[found.user];
1979	    if (userEntries) {
1980	      mentions[found.user] = userEntries.map((e) =>
1981	        e.id === mentionId ? { ...e, isRead: true } : e,
1982	      );
1983	      await writeMentionsFile(trackerDir, mentions);
1984	    }
1985	
1986	    return { result: "OK" };
1987	  }
1988	
1989	  /**
1990	   * Mark a mention as unread.
1991	   *
1992	   * Auth constraint: only the mentionedUser can mark a mention as unread.
1993	   *
1994	   * @param mentionId - The mention ID to mark as unread
1995	   * @returns `{ result: "OK" }` on success, or a AgentrackError
1996	   * @throws {AgentrackError} NOT_INITIALIZED if no `.agentrack/` directory
1997	   * @throws {AgentrackError} MENTION_NOT_FOUND if the mention ID doesn't exist
1998	   * @throws {AgentrackError} MENTION_ACCESS_DENIED if the authenticated user is not the mentioned user
1999	   * @throws {AgentrackError} TOKEN_REQUIRED if no token provided in auth-required mode
2000	   */
2001	  async mentionsUnread(mentionId: string): Promise<MentionsUnreadResult> {
2002	    const trackerDir = resolveTrackerDir(this.cwd);
2003	    if (!trackerDir) {
2004	      throw new AgentrackError(
2005	        ErrorCodes.NOT_INITIALIZED.result,
2006	        "No .agentrack/ directory found. Run `agt init` first.",
2007	        ErrorCodes.NOT_INITIALIZED.exitCode,
2008	      );
2009	    }
2010	
2011	    const config = await readJSON<ConfigFile>(join(trackerDir, "config.json"));
2012	    const users = await readJSON<UsersFile>(join(trackerDir, "users.json"));
2013	    const authResult = resolveAuthor({ config, users, requiresWrite: true });
2014	    if (authResult instanceof AgentrackError) return authResult;
2015	    const callerName = authResult.author;
2016	
2017	    const found = findMentionById(trackerDir, mentionId);
2018	    if (!found) {
2019	      return new AgentrackError(
2020	        ErrorCodes.MENTION_NOT_FOUND.result,
2021	        `Mention \`${mentionId}\` not found.`,
2022	        ErrorCodes.MENTION_NOT_FOUND.exitCode,
2023	      );
2024	    }
2025	
2026	    if (found.entry.mentionedUser !== callerName) {
2027	      return new AgentrackError(
2028	        ErrorCodes.MENTION_ACCESS_DENIED.result,
